import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type RocketLaunchProps = Record<string, any>;

// Helper for generating deterministic stars
const generateStars = (count: number, width: number, height: number, seed: string) => {
  return new Array(count).fill(true).map((_, i) => ({
    x: random(`star-x-${seed}-${i}`) * width,
    y: random(`star-y-${seed}-${i}`) * height,
    size: random(`star-size-${seed}-${i}`) * 3 + 1,
    speed: random(`star-speed-${seed}-${i}`) * 15 + 2,
    opacity: random(`star-opacity-${seed}-${i}`) * 0.5 + 0.3,
  }));
};

// Helper for exhaust particles
const generateExhaust = (count: number, seed: string) => {
  return new Array(count).fill(true).map((_, i) => ({
    xOffset: (random(`ex-x-${seed}-${i}`) - 0.5) * 40, // spread
    speed: random(`ex-spd-${seed}-${i}`) * 10 + 15,
    phase: random(`ex-ph-${seed}-${i}`) * 100, // random start time
    size: random(`ex-sz-${seed}-${i}`) * 20 + 10,
  }));
};

const RocketLaunch: React.FC<RocketLaunchProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 8,
  rocketPrimaryColor = "#e11d48",
  rocketSecondaryColor = "#cbd5e1",
  rocketWindowColor = "#38bdf8",
  fireCoreColor = "#fef08a",
  fireOuterColor = "#f97316",
  starColor = "#ffffff",
  starCount = 100,
}) => {
  // Load fonts (even if unused, required by protocol structure)
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Star Generation
  const stars = useMemo(() => generateStars(starCount, width, height, "stars-v1"), [starCount, width, height]);
  
  // Exhaust Generation
  const exhaustParticles = useMemo(() => generateExhaust(40, "exhaust-v1"), []);

  // Animation Timings
  const durationInFrames = durationInSeconds * fps;
  const launchDuration = fps * 1.5; // 1.5s to enter
  const exitDuration = fps * 1.5;   // 1.5s to leave
  const exitStart = durationInFrames - exitDuration;

  // 1. Entrance (Rise from bottom)
  const entranceOffset = interpolate(
    frame,
    [0, launchDuration],
    [height * 0.6, 0],
    { extrapolateRight: "clamp", easing: Easing.out(Easing.back(1)) }
  );

  // 2. Exit (Fly off top)
  const exitOffset = interpolate(
    frame,
    [exitStart, durationInFrames],
    [0, -height],
    { extrapolateLeft: "clamp", easing: Easing.in(Easing.poly(3)) }
  );

  // Combined Vertical Position (Centered mostly)
  const rocketBaseY = height / 2;
  const rocketY = rocketBaseY + entranceOffset + exitOffset;

  // 3. Rumble/Vibration
  const rumbleX = Math.sin(frame * 0.8) * 3;
  const rumbleY = Math.cos(frame * 1.2) * 3;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* --- BACKGROUND STARS --- */}
      {!transparentBackground && stars.map((star, i) => {
        // Parallax effect: stars move down faster as rocket "speeds up"
        const speedMultiplier = interpolate(frame, [0, durationInFrames], [1, 5]); 
        const animatedY = (star.y + frame * star.speed * speedMultiplier) % height;
        
        return (
          <div
            key={`star-${i}`}
            style={{
              position: "absolute",
              left: star.x,
              top: animatedY,
              width: star.size,
              height: star.size,
              backgroundColor: starColor,
              borderRadius: "50%",
              opacity: star.opacity,
            }}
          />
        );
      })}

      {/* --- ROCKET CONTAINER --- */}
      <div
        style={{
          position: "absolute",
          left: width / 2,
          top: rocketY,
          transform: `translate(-50%, -50%) translate(${rumbleX}px, ${rumbleY}px)`,
          width: 200,
          height: 400,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        
        {/* --- EXHAUST FIRE --- */}
        <div style={{ position: "absolute", top: 280, left: "50%", transform: "translateX(-50%)" }}>
           {exhaustParticles.map((p, i) => {
             // Cycle the particles
             const travelDist = 300;
             const cycle = (frame * p.speed + p.phase) % travelDist;
             
             // Fade out and shrink as they move down
             const opacity = interpolate(cycle, [0, travelDist * 0.8], [1, 0]);
             const scale = interpolate(cycle, [0, travelDist], [1, 0.2]);
             
             // Color transition from core to outer
             const isCore = i % 2 === 0;
             const color = isCore ? fireCoreColor : fireOuterColor;

             return (
               <div
                key={`fire-${i}`}
                style={{
                  position: "absolute",
                  left: p.xOffset,
                  top: cycle,
                  width: p.size,
                  height: p.size,
                  backgroundColor: color,
                  borderRadius: "50%",
                  opacity: opacity,
                  transform: `translate(-50%, 0) scale(${scale})`,
                  boxShadow: `0 0 10px ${color}`,
                }}
               />
             );
           })}
        </div>

        {/* --- ROCKET SVG --- */}
        <svg
          width="160"
          height="300"
          viewBox="0 0 160 300"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          style={{ zIndex: 10, filter: "drop-shadow(0px 10px 10px rgba(0,0,0,0.3))" }}
        >
          {/* Left Fin */}
          <path
            d="M30 200 L0 280 L50 260 Z"
            fill={rocketSecondaryColor}
          />
          {/* Right Fin */}
          <path
            d="M130 200 L160 280 L110 260 Z"
            fill={rocketSecondaryColor}
          />
          {/* Main Body */}
          <path
            d="M80 0 C30 0 30 100 30 250 C30 270 40 280 80 280 C120 280 130 270 130 250 C130 100 130 0 80 0 Z"
            fill={rocketPrimaryColor}
          />
          {/* Central Fin (Vertical) */}
          <path
            d="M80 200 L80 280"
            stroke={rocketSecondaryColor}
            strokeWidth="4"
          />
          {/* Window Frame */}
          <circle cx="80" cy="100" r="35" fill={rocketSecondaryColor} />
          {/* Window Glass */}
          <circle cx="80" cy="100" r="28" fill={rocketWindowColor} />
          {/* Window Reflection */}
          <path d="M70 85 Q80 80 90 85" stroke="rgba(255,255,255,0.6)" strokeWidth="3" fill="none" />
        </svg>

      </div>
    </AbsoluteFill>
  );
};

export default RocketLaunch;